        std::cout << "Closing socket: " << *sockfd << "\n";
        close(*sockfd);
    }
    delete sockfd;
}

std::shared_ptr<int> createSocket() {
    int* sockfd = new int(socket(AF_INET, SOCK_STREAM, 0));
    if (*sockfd < 0) {
        delete sockfd;
        return nullptr;
    }

    return std::shared_ptr<int>(sockfd, closeSocket);
}

int main() {
