    std::unordered_set<T*> allocatedSet;  // Track allocated objects
    std::mutex mtx;

public:
    T* allocate() {
        std::lock_guard<std::mutex> lock(mtx);
        if (freeList.empty()) return nullptr;

        T* obj = freeList.back();
        freeList.pop_back();

        allocatedSet.insert(obj);  // Mark as allocated
        return obj;
    }

