      if (this == &other) return *this;

      // Destroy existing resources
      for (size_t i = 0; i < sz; ++i) {
          data[i].~T();
      }
      ::operator delete(data);

      // Steal from other
      data = other.data;
      sz = other.sz;
      cap = other.cap;

      // Leave other valid
      other.data = nullptr;
      other.sz = 0;
      other.cap = 0;

      return *this;
  }
