      // noexcept guarantees no exceptions
      // Allows safe use in containers
      // std::vector can use move in reallocation
  }

  // If NOT noexcept:
  // std::vector<Vector<int>> uses copy (slow!)
  // to maintain strong exception guarantee
  ```

