      string error;
      if (!validateConfig(j, error)) {
          throw std::invalid_argument(error);
      }

      // Config validated, proceed safely:
      Type type = stringToType(j["type"]);
      int rate = j["sampleRate"];

      auto sensor = make_unique<Sensor>(type);
      sensor->setSampleRate(rate);
      return sensor;
  }
