public:
    void onCollisionDetected(const CollisionEvent& event) override {
        cout << "🔔 COLLISION WARNING: " << event.distance << "m\n";
        playWarningSound();
    }
};

class DataLogger : public CollisionObserver {
public:
    void onCollisionDetected(const CollisionEvent& event) override {
        logToFile("Collision event: " + event.toString());
    }
};

// Setup
