    std::cout << "Parallel:   " << par_time.count() << "ms\n";
    std::cout << "Speedup:    " << (double)seq_time.count() / par_time.count() << "x\n";

    // Typical output on 8-core CPU:
    // Sequential: 45ms
    // Parallel:   8ms
    // Speedup:    5.6x
}

