    IRepository* repo;

public:
    void createUser(const std::string& name, const std::string& email) {
        // Validation
        if (name.empty()) throw std::invalid_argument("Name required");

        User user{name, email};
        repo->save(user);  // Call data layer
    }
};

// Layer 1: Data (Persistence)
