// Event bus for commands
std::queue<std::unique_ptr<Command>> commandQueue;

// Publish command
commandQueue.push(std::make_unique<MoveCommand>(&playerX, 10));

// Process commands
while (!commandQueue.empty()) {
    commandQueue.front()->execute();
    commandQueue.pop();
