// Simulate CPU-bound work
int process_batch_job() {
    static int job_counter = 0;
    job_counter++;

    // Simulate computation
    int result = 0;
    for (int i = 0; i < 1000000; i++) {
        result += i;
    }

    if (job_counter % 100 == 0) {
        std::cout << "[JOB] Processed " << job_counter << " batches\n";
    }

    return result;
}

