    timeout.tv_sec = 10;
    timeout.tv_usec = 0;

    fd_set read_fds = master_fds;
    int ready = select(max_fd + 1, &read_fds, NULL, NULL, &timeout);

    if (ready == 0) {
        std::cout << "10 seconds elapsed\n";
        send_pings_to_all_clients();
    }
}
```

