const char* event_to_string(uint32_t events) {
    static char buf[256];
    buf[0] = '\0';

    if (events & EPOLLIN) strcat(buf, "EPOLLIN|");
    if (events & EPOLLOUT) strcat(buf, "EPOLLOUT|");
    if (events & EPOLLERR) strcat(buf, "EPOLLERR|");
    if (events & EPOLLHUP) strcat(buf, "EPOLLHUP|");
