    if (events & EPOLLET) strcat(buf, "EPOLLET|");
    if (events & EPOLLONESHOT) strcat(buf, "EPOLLONESHOT|");

    // Remove trailing '|'
    size_t len = strlen(buf);
    if (len > 0) buf[len - 1] = '\0';

    return buf;
}

