// Mock epoll for testing
class MockEpoll {
public:
    std::queue<struct epoll_event> pending_events;

    int mock_epoll_wait(struct epoll_event *events, int maxevents, int timeout) {
        int n = 0;
        while (n < maxevents && !pending_events.empty()) {
