#include <iostream>
#include <ranges>

namespace views = std::views;

auto fibonacci() {
    return views::iota(0)
        | views::transform([](int n) {
            int a = 0, b = 1;
            for (int i = 0; i < n; ++i) {
                int next = a + b;
                a = b;
                b = next;
            }
            return a;
        });
}

int main() {
    auto first_20_fibs = fibonacci() | views::take(20);

    std::cout << "First 20 Fibonacci numbers:\n";
