    auto pipeline = take(
        map(
            filter(naturals(), [](int n) { return n % 2 == 0; }),
            [](int n) { return n * n; }
        ),
        5
    );

    for (int val : pipeline) {
        std::cout << val << " ";
    }
    std::cout << '\n';
}

