    SmartPointer<Base> ptr1 = new Derived;

    // ✅ Explicit conversion required (unrelated types)
    SmartPointer<int> ptr2 = SmartPointer<int>(new int);
}

template<typename T>
   struct Optional {
       template<typename U>
       explicit(!std::is_convertible_v<U, T>)
       Optional(U&& value) { /* ... */ }
   };

template<typename T>
   class unique_ptr {
       template<typename U>
       explicit(!std::is_convertible_v<U*, T*>)
       unique_ptr(unique_ptr<U>&& other);
   };

