// math_module.ixx - Module Interface
export module math;

export int add(int a, int b) { return a + b; }
export int subtract(int a, int b) { return a - b; }

// math.h - Header Compatibility (for legacy code)
#ifndef MATH_H
#define MATH_H

#ifdef __cpp_modules
// If modules supported, just import
import math;
#else
// Otherwise, provide traditional declarations
int add(int a, int b);
int subtract(int a, int b);
#endif

#endif

// math_impl.cpp - Implementation for header users
#ifndef __cpp_modules
int add(int a, int b) { return a + b; }
int subtract(int a, int b) { return a - b; }
#endif

// modern_code.cpp - Uses modules
import math;

// legacy_code.cpp - Uses headers
#include "math.h"

// container.ixx
export module container;

export template<typename T>
class MyVector {
    T* data_;
    size_t size_;
    size_t capacity_;

public:
    MyVector() : data_(nullptr), size_(0), capacity_(0) {}

    void push_back(const T& value) {
        if (size_ == capacity_) {
            reserve(capacity_ == 0 ? 1 : capacity_ * 2);
        }
        data_[size_++] = value;
    }

    T& operator[](size_t index) { return data_[index]; }
    size_t size() const { return size_; }

private:
    void reserve(size_t new_capacity);
};

// Implementation must be in interface for templates
template<typename T>
void MyVector<T>::reserve(size_t new_capacity) {
    T* new_data = new T[new_capacity];
    for (size_t i = 0; i < size_; ++i) {
        new_data[i] = data_[i];
    }
    delete[] data_;
    data_ = new_data;
    capacity_ = new_capacity;
}

// main.cpp
import container;

int main() {
    MyVector<int> vec;
    vec.push_back(1);
    vec.push_back(2);
    vec.push_back(3);
}

