std::vector<T> drain() {
    std::lock_guard<std::mutex> lock(mutex_);

    std::vector<T> result;
    result.reserve(queue_.size());

    while (!queue_.empty()) {
        result.push_back(std::move(queue_.front()));
        queue_.pop();
    }

    // Queue now empty - notify all waiting producers
    not_full_.notify_all();

    return result;
}

