    // In production: add to retirement list
    while (old_head.ptr) {
        Node* next = old_head.ptr->next;
        delete old_head.ptr;  // Simplified (unsafe if other threads accessing)
        old_head.ptr = next;
    }

    size_.store(0, std::memory_order_relaxed);
