#include <iostream>
#include <chrono>

void task(int id) {
    std::cout << "Task " << id << " starting on thread "
              << std::this_thread::get_id() << '\n';

    std::this_thread::sleep_for(std::chrono::milliseconds(100));

    std::cout << "Task " << id << " completed\n";
}

int main() {
    ThreadPool pool(4);  // 4 worker threads

    // Submit 10 tasks
    for (int i = 0; i < 10; ++i) {
        pool.submit(task, i);
    }

    // Wait for all tasks to complete
    std::this_thread::sleep_for(std::chrono::seconds(1));

    pool.shutdown();

    std::cout << "Total tasks processed: " << pool.total_tasks() << '\n';

    return 0;
}

#include <iostream>
#include <numeric>
#include <vector>

int sum_range(int start, int end) {
    int sum = 0;
    for (int i = start; i < end; ++i) {
        sum += i;
    }
    return sum;
}

int main() {
    ThreadPool pool(4);

    std::vector<std::future<int>> futures;

    // Submit 10 parallel sum tasks
    for (int i = 0; i < 10; ++i) {
        futures.push_back(
            pool.submit_with_result(sum_range, i * 1000, (i + 1) * 1000)
        );
    }

    // Collect results
    int total = 0;
    for (auto& fut : futures) {
        total += fut.get();  // Blocks until result ready
    }

    std::cout << "Total sum: " << total << '\n';

    pool.shutdown();

    return 0;
