iterator erase(iterator pos) {
    if (pos < begin() || pos >= end()) {
        throw std::out_of_range("Invalid iterator");
    }

    size_t index = pos - begin();

    // Destroy element
    data_[index].~T();

    // Shift elements left
    for (size_t i = index; i < size_ - 1; ++i) {
        new (data_ + i) T(std::move(data_[i + 1]));
        data_[i + 1].~T();
    }

    --size_;

    return begin() + index;
}

