`std::function_ref` is a **non-owning**, **lightweight** function wrapper:

```cpp
template<typename R, typename... Args>
class function_ref<R(Args...)> {
    void* obj_;
    R(*invoke_)(void*, Args...);

public:
    template<typename F>
    function_ref(F& f) {
        obj_ = &f;
        invoke_ = [](void* ptr, Args... args) -> R {
            return (*static_cast<F*>(ptr))(std::forward<Args>(args)...);
