    auto func_ms = std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count();

    std::cout << "Direct: " << direct_ms << " ms\n";
    std::cout << "Function: " << func_ms << " ms\n";
    std::cout << "Overhead: " << (func_ms - direct_ms) << " ms\n";

    return 0;
}

