bool insert(const K& key, const V& value) {
    size_t index = std::hash<K>{}(key) % buckets_.size();

    auto& bucket = buckets_[index];

    // Check for existing key
    for (auto& [k, v] : bucket) {
        if (k == key) {
            return false;  // Key exists, don't insert
        }
    }

    bucket.push_back({key, value});
    size_++;
    return true;
}

