subsections.content:
**Principle:** Resource lifetime bound to object lifetime.

**Benefits:**
- Automatic cleanup (no manual close())
- Exception-safe
- No resource leaks

**Pattern:**
```cpp
class Resource {
public:
    Resource() { /* acquire */ }
    ~Resource() { /* release */ }
};

{
    Resource r;  // Acquired
    // Use resource
}  // Auto-released (destructor called)
```

---

**C-style (manual):**
```cpp
int fd = open("file.txt", O_RDONLY);
// ... use fd ...
close(fd);  // ← Easy to forget! Leak if exception thrown
```

**RAII wrapper:**
```cpp
FileDescriptor fd("file.txt", O_RDONLY);
// ... use fd ...
// Auto-closed on scope exit
```

---



```cpp
#include <fcntl.h>
#include <unistd.h>
#include <stdexcept>
#include <utility>

class FileDescriptor {
private:
    int fd_;

public:
    FileDescriptor(const char* path, int flags, mode_t mode = 0644)
        : fd_(open(path, flags, mode))
    {
        if (fd_ == -1) {
            throw std::runtime_error("Failed to open file");
        }
    }

    explicit FileDescriptor(int fd = -1) : fd_(fd) {}

    ~FileDescriptor() {
        if (fd_ != -1) {
            close(fd_);
        }
    }

    FileDescriptor(const FileDescriptor&) = delete;
    FileDescriptor& operator=(const FileDescriptor&) = delete;

    FileDescriptor(FileDescriptor&& other) noexcept : fd_(other.fd_) {
        other.fd_ = -1;
    }

    FileDescriptor& operator=(FileDescriptor&& other) noexcept {
        if (this != &other) {
            if (fd_ != -1) {
                close(fd_);
            }
            fd_ = other.fd_;
            other.fd_ = -1;
        }
        return *this;
    }

    int get() const { return fd_; }

    ssize_t read(void* buf, size_t count) {
        return ::read(fd_, buf, count);
    }

    ssize_t write(const void* buf, size_t count) {
        return ::write(fd_, buf, count);
    }

    void close_fd() {
        if (fd_ != -1) {
            close(fd_);
            fd_ = -1;
        }
    }

    bool is_open() const {
        return fd_ != -1;
    }
};
```

---

theory.full_text:
#### 1. RAII (Resource Acquisition Is Initialization)

**Principle:** Resource lifetime bound to object lifetime.

**Benefits:**
- Automatic cleanup (no manual close())
- Exception-safe
- No resource leaks

**Pattern:**
```cpp
class Resource {
public:
    Resource() { /* acquire */ }
    ~Resource() { /* release */ }
};

{
    Resource r;  // Acquired
    // Use resource
}  // Auto-released (destructor called)
```

