        size_t current_tail = tail_;
        size_t next_tail = (current_tail + 1) % Size;

        if (next_tail == head_) {
            return false;  // Full
        }

        buffer_[current_tail] = item;
        tail_ = next_tail;  // Bug: not atomic update!
        return true;
    }

    bool pop(T& item) {
        if (head_ == tail_) {
            return false;  // Empty
        }

        item = buffer_[head_];
        head_ = (head_ + 1) % Size;
        return true;
    }
};

