subsections.content:
Track how many strings share the same buffer:

```
String s1 = "hello";  // refcount = 1
String s2 = s1;        // refcount = 2 (shared)
s2[0] = 'H';          // Copy buffer (refcount s1=1, s2=1)
```

---



```cpp
#include <cstring>
#include <atomic>
#include <iostream>

class COWString {
private:
    struct Buffer {
        std::atomic<int> refcount{1};
        size_t length;
        char data[1];  // Flexible array member

        static Buffer* create(const char* str, size_t len) {
            Buffer* buf = static_cast<Buffer*>(
                ::operator new(sizeof(Buffer) + len)
            );

            buf->refcount.store(1);
            buf->length = len;
            std::memcpy(buf->data, str, len + 1);  // +1 for null

            return buf;
        }

        void addRef() {
            refcount.fetch_add(1, std::memory_order_relaxed);
        }

        void release() {
            if (refcount.fetch_sub(1, std::memory_order_release) == 1) {
                std::atomic_thread_fence(std::memory_order_acquire);
                ::operator delete(this);
            }
        }
    };

    Buffer* buffer_;

    void detach() {
        if (buffer_->refcount.load(std::memory_order_relaxed) > 1) {
            // Copy buffer
            Buffer* new_buf = Buffer::create(buffer_->data, buffer_->length);
            buffer_->release();
            buffer_ = new_buf;
        }
    }

public:
    COWString(const char* str = "")
        : buffer_(Buffer::create(str, std::strlen(str)))
    {}

    COWString(const COWString& other)
        : buffer_(other.buffer_)
    {
        buffer_->addRef();
    }

    COWString& operator=(const COWString& other) {
        if (this != &other) {
            buffer_->release();
            buffer_ = other.buffer_;
            buffer_->addRef();
        }
        return *this;
    }

    ~COWString() {
        buffer_->release();
    }

    const char* c_str() const {
        return buffer_->data;
    }

    size_t length() const {
        return buffer_->length;
    }

    char& operator[](size_t index) {
        detach();  // Copy-on-write!
        return buffer_->data[index];
    }

    const char& operator[](size_t index) const {
        return buffer_->data[index];
    }
};
```

---

theory.full_text:
#### 1. Copy-on-Write Concept

**Idea:** Share data until modification, then copy.

**Benefits:**
- Cheap copies (no allocation)
- Lazy duplication (only when needed)

**Use cases:**
- Strings (old std::string implementations)
- Large buffers
- Fork() in Unix

---

#### 2. Reference Counting

Track how many strings share the same buffer:

```
String s1 = "hello";  // refcount = 1
String s2 = s1;        // refcount = 2 (shared)
s2[0] = 'H';          // Copy buffer (refcount s1=1, s2=1)
```

---



```cpp
#include <cstring>
#include <atomic>
#include <iostream>

class COWString {
private:
    struct Buffer {
        std::atomic<int> refcount{1};
        size_t length;
        char data[1];  // Flexible array member

        static Buffer* create(const char* str, size_t len) {
            Buffer* buf = static_cast<Buffer*>(
                ::operator new(sizeof(Buffer) + len)
            );

            buf->refcount.store(1);
            buf->length = len;
            std::memcpy(buf->data, str, len + 1);  // +1 for null

            return buf;
        }

        void addRef() {
            refcount.fetch_add(1, std::memory_order_relaxed);
        }

        void release() {
            if (refcount.fetch_sub(1, std::memory_order_release) == 1) {
                std::atomic_thread_fence(std::memory_order_acquire);
                ::operator delete(this);
            }
        }
    };

    Buffer* buffer_;

    void detach() {
        if (buffer_->refcount.load(std::memory_order_relaxed) > 1) {
            // Copy buffer
            Buffer* new_buf = Buffer::create(buffer_->data, buffer_->length);
            buffer_->release();
            buffer_ = new_buf;
        }
    }

public:
    COWString(const char* str = "")
        : buffer_(Buffer::create(str, std::strlen(str)))
    {}

    COWString(const COWString& other)
        : buffer_(other.buffer_)
    {
        buffer_->addRef();
    }

    COWString& operator=(const COWString& other) {
        if (this != &other) {
            buffer_->release();
            buffer_ = other.buffer_;
            buffer_->addRef();
        }
        return *this;
    }

    ~COWString() {
        buffer_->release();
    }

    const char* c_str() const {
        return buffer_->data;
    }

    size_t length() const {
        return buffer_->length;
    }

    char& operator[](size_t index) {
        detach();  // Copy-on-write!
        return buffer_->data[index];
    }

    const char& operator[](size_t index) const {
        return buffer_->data[index];
    }
};
```

