        std::unique_lock<std::mutex> lock(mutex_);

        // Wait if queue full (backpressure)
        cv_full_.wait(lock, [this] {
            return queue_.size() < max_capacity_ || stop_;
        });

        queue_.push(msg);
        cv_empty_.notify_one();
    }
};
```

