}

void demonstrateSafeException() {
    cout << "\n### SAFE: Exception-Safe RAII ###\n";
    auto data = make_unique<double[]>(100000);  // ✅ RAII allocation
    cout << "Allocated 100000 doubles (RAII)\n";

    if (true) {
