    cout << "\n### DANGER: Dangling Pointer ###\n";
    double* ptr = new double[10];
    cout << "Allocated array\n";
    delete[] ptr;
    cout << "Freed array\n";

    // ❌ ptr is now dangling
    // cout << ptr[0];  // UB: accessing freed memory

