// ❌ Poor hash function - many collisions
struct PoorHash {
    size_t operator()(int x) const {
        return x % 10;  // Only 10 possible hash values
    }
};

// ✅ Good hash function - uniform distribution
struct GoodHash {
    size_t operator()(int x) const {
        return std::hash<int>{}(x);  // Standard hash
    }
